UPDATE sys_user
real_name = #{realName}, phone = #{phone}, email = #{email}, dept_id = #{deptId},
WHERE id = #{id}

UPDATE sys_user
SET password = #{password},
    must_change_password = #{mustChangePassword}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE sys_user_role SET is_deleted = 1, deleted_at = NOW(6), deleted_by = COALESCE(#{operatorId}, 'DB') WHERE user_id = #{userId} AND is_deleted = 0
AND role_id NOT IN
#{roleId}
